        2 * i + 2
    }

    /* 获取父节点的索引 */
    private func parent(i: Int) -> Int {
        (i - 1) / 2 // 向下整除
    }

    /* 交换元素 */
    private func swap(i: Int, j: Int) {
        maxHeap.swapAt(i, j)
    }

    /* 获取堆大小 */
    func size() -> Int {
        maxHeap.count
    }

    /* 判断堆是否为空 */
    func isEmpty() -> Bool {
        size() == 0
    }

    /* 访问堆顶元素 */
    func peek() -> Int {
        maxHeap[0]
